const ctx = $('01.2 Build run context').item.json;
const ctxErr = $input.first().json;
return [{
  json: {
    correlationId: ctx.correlationId,
    status: "nicht_pruefbar",
    routing: "technical_review",
    failedStep: "02.5L Parse local OCR/LLM output",
    errorCode: "LOCAL_LLM_OUTPUT_PARSE_FAILED",
    explanation: (ctxErr.error && (ctxErr.error.message || ctxErr.error)) || ctxErr.message || "The local LLM's response could not be parsed into the expected JSON shape.",
    invoice: null,
    controls: null,
    organizationId: ctx.organizationId,
    processingPath: ctx.processingPath,
    aiExecutionProfile: ctx.aiExecutionProfile,
    aiProvider: "local-openai-compatible",
    modelId: null,
    modelVersion: null,
    processingLocation: "local",
    promptVersion: null,
    fallbackUsed: false,
  },
}];

// TEMPORARY: mirrors the dotted-path fieldEvidence shape from
// facturx/phase1/normalize/pdf_adapter.py (method/confidence/locator/
// rawValue/state) so this stays trivially convergeable once a real adapter
// exists -- but the confidence values below are NOT calibrated. Neither the
// cloud (Gemini) nor local structured-JSON output carries a native
// per-field confidence.
//
// Every field the model reports as a real value gets a fixed placeholder
// confidence (0.85, just above the 0.70 default threshold used everywhere
// else in this project). Every field reported as "not found" is treated as
// NOT_EXTRACTED (confidence 0.0, state "not_extracted"), NOT as a confirmed
// absence -- there is no calibrated signal to trust an LLM's own "not
// found" claim as a real business fact yet. This always forces
// not_reliable/nicht_pruefbar for that field, never a confident
// MISSING_FIELD failure, matching the project-wide rule that low-confidence
// or missing OCR fields must route to human review, never an automatic pass.
//
// Shared by both provider lanes (2026-08-11, dev-stack/AI-selection round):
// "02.5 Parse OCR/LLM output" (cloud) and "02.5L Parse local OCR/LLM
// output" (local) both emit the same {invoice_extracted, aiMeta} shape, so
// this single node produces one identical canonical contract regardless of
// which lane ran -- per the AI-selection spec's convergence requirement.
const PLACEHOLDER_FOUND_CONFIDENCE = 0.85;
const parsed = $input.first().json;
const g = parsed.invoice_extracted;

function emit(rawValue, locator) {
  const found = typeof rawValue === "string" && rawValue.trim() && rawValue.trim().toLowerCase() !== "not found";
  return {
    value: found ? rawValue.trim() : null,
    evidence: {
      method: "llm",
      confidence: found ? PLACEHOLDER_FOUND_CONFIDENCE : 0.0,
      locator,
      rawValue: rawValue,
      state: found ? "extracted" : "not_extracted",
    },
  };
}

const buyerName = emit(g["Name (Buyer)"], "invoice.buyer.name");
const buyerStreet = emit(g["Address (Buyer)"], "invoice.buyer.address.street");
const buyerPostal = emit(g["Zip (Buyer)"], "invoice.buyer.address.postalCode");
const buyerCity = emit(g["City (Buyer)"], "invoice.buyer.address.city");
const buyerCountry = emit(g["Country (Buyer)"], "invoice.buyer.address.countryCode");

const fieldEvidence = {
  "invoice.buyer.name": buyerName.evidence,
  "invoice.buyer.address.street": buyerStreet.evidence,
  "invoice.buyer.address.postalCode": buyerPostal.evidence,
  "invoice.buyer.address.city": buyerCity.evidence,
  "invoice.buyer.address.countryCode": buyerCountry.evidence,
};

function orNull(v) {
  return v === "not found" ? null : v;
}

const invoice = {
  invoiceNumber: orNull(g["Invoice No"]),
  issueDate: orNull(g["Invoice Date"]),
  supplier: {
    name: orNull(g["Name (Seller)"]),
    vatId: orNull(g["VAT-ID (Seller)"]),
    address: {
      street: orNull(g["Address (Seller)"]),
      postalCode: orNull(g["Zip (Seller)"]),
      city: orNull(g["City (Seller)"]),
      countryCode: orNull(g["Country (Seller)"]),
    },
  },
  buyer: {
    name: buyerName.value,
    vatId: orNull(g["VAT-ID (Buyer)"]),
    address: {
      street: buyerStreet.value,
      postalCode: buyerPostal.value,
      city: buyerCity.value,
      countryCode: buyerCountry.value,
    },
  },
};

const ctx = $('01.2 Build run context').item.json;
const org = $('01.6 Resolve organization profile (concept)').item.json;

return [
  {
    json: {
      correlationId: ctx.correlationId,
      organizationId: ctx.organizationId,
      processingPath: ctx.processingPath,
      aiExecutionProfile: ctx.aiExecutionProfile,
      buyerMasterData: org.buyerMasterData,
      invoice,
      fieldEvidence,
      rawExtractionText: parsed.gemini_raw_text || parsed.raw_text,
      aiMeta: parsed.aiMeta,
    },
  },
];

// TEMPORARY: replicates facturx/phase1/controls/executor.py::evaluate_org_001
// and its _check/_combine/_normalize_for_match helpers exactly (same 5
// fields, same 0.70 confidence threshold, same case/whitespace-insensitive
// comparison, same severity/reason-code shape) so this control's output is
// structurally interchangeable with the real one -- see the README for what
// a real convergence would require.
const THRESHOLD = 0.70;
const CONTROL_ID = "ORG-001";
const TITLE = "Stammdatenabgleich Rechnungsempfänger";
const RULE_VERSION = "1.0.0";

function normalizeForMatch(value) {
  return (value || "").toString().trim().toLowerCase().replace(/\s+/g, " ");
}

function checkField(value, evidence) {
  const confidence = evidence.confidence;
  if (confidence < THRESHOLD) {
    return {
      outcome: "not_reliable", reasonCodes: ["LOW_CONFIDENCE_EXTRACTION"], evidenceRefs: [evidence.locator],
      message: `${evidence.locator}: extraction confidence ${confidence.toFixed(2)} is below the ${THRESHOLD.toFixed(2)} reliability threshold.`,
    };
  }
  if (value === null || value === undefined || (typeof value === "string" && !value.trim())) {
    return { outcome: "failed", reasonCodes: ["MISSING_FIELD"], evidenceRefs: [evidence.locator], message: `${evidence.locator}: required value is missing.` };
  }
  return { outcome: "passed", reasonCodes: [], evidenceRefs: [evidence.locator], message: null };
}

function combine(parts) {
  const outcomes = parts.map((p) => p.outcome);
  const reasonCodes = [...new Set(parts.flatMap((p) => p.reasonCodes))].sort();
  const evidenceRefs = [...new Set(parts.flatMap((p) => p.evidenceRefs))].sort();
  const messages = parts.map((p) => p.message).filter(Boolean);
  const combinedMessage = messages.length ? messages.join(" ") : null;
  if (outcomes.includes("not_reliable")) return { outcome: "not_reliable", reasonCodes, evidenceRefs, message: combinedMessage };
  if (outcomes.includes("failed")) return { outcome: "failed", reasonCodes, evidenceRefs, message: combinedMessage };
  return { outcome: "passed", reasonCodes: [], evidenceRefs, message: null };
}

const ctx = $input.first().json;
const invoice = ctx.invoice;
const fieldEvidence = ctx.fieldEvidence;
const masterData = ctx.buyerMasterData;

const checks = [
  checkField(invoice.buyer.name, fieldEvidence["invoice.buyer.name"]),
  checkField(invoice.buyer.address.street, fieldEvidence["invoice.buyer.address.street"]),
  checkField(invoice.buyer.address.postalCode, fieldEvidence["invoice.buyer.address.postalCode"]),
  checkField(invoice.buyer.address.city, fieldEvidence["invoice.buyer.address.city"]),
  checkField(invoice.buyer.address.countryCode, fieldEvidence["invoice.buyer.address.countryCode"]),
];
const combined = combine(checks);

let result;
if (combined.outcome !== "passed") {
  result = {
    controlId: CONTROL_ID, title: TITLE, outcome: combined.outcome,
    severity: "blocking", reasonCodes: combined.reasonCodes, evidenceRefs: combined.evidenceRefs,
    ruleVersion: RULE_VERSION, message: combined.message, details: null,
  };
} else {
  const fieldPairs = [
    ["invoice.buyer.name", invoice.buyer.name, masterData.name],
    ["invoice.buyer.address.street", invoice.buyer.address.street, masterData.street],
    ["invoice.buyer.address.postalCode", invoice.buyer.address.postalCode, masterData.postalCode],
    ["invoice.buyer.address.city", invoice.buyer.address.city, masterData.city],
    ["invoice.buyer.address.countryCode", invoice.buyer.address.countryCode, masterData.countryCode],
  ];
  const mismatches = fieldPairs
    .filter(([, actual, expected]) => normalizeForMatch(actual) !== normalizeForMatch(expected))
    .map(([f, actual, expected]) => ({ field: f, expected, actual }));

  if (mismatches.length > 0) {
    const message = "Buyer data does not match approved organization master data: " +
      mismatches.map((m) => `${m.field} expected ${JSON.stringify(m.expected)}, got ${JSON.stringify(m.actual)}`).join("; ");
    result = {
      controlId: CONTROL_ID, title: TITLE, outcome: "failed", severity: "blocking",
      reasonCodes: ["MASTER_DATA_MISMATCH"], evidenceRefs: combined.evidenceRefs,
      ruleVersion: RULE_VERSION, message, details: { mismatches },
    };
  } else {
    result = {
      controlId: CONTROL_ID, title: TITLE, outcome: "passed", severity: "none",
      reasonCodes: [], evidenceRefs: combined.evidenceRefs, ruleVersion: RULE_VERSION,
      message: null, details: null,
    };
  }
}

return [{ json: { ...ctx, org001: result } }];

// Aggregation mirrors facturx/phase1/controls/aggregate.py's mapping for a
// single control exactly: not_reliable -> nicht_pruefbar/prioritized_review,
// failed+blocking -> klaerung_erforderlich/prioritized_review, passed ->
// unauffaellig/standard_review. "technical_review" (used elsewhere in this
// workflow) is deliberately NOT one of the real API's routing values -- it
// only appears upstream of this node, for genuine service/input failures.
//
// Also carries the audit fields required by the AI-selection spec
// (2026-08-11 round): processingPath, aiExecutionProfile, aiProvider,
// modelId, modelVersion, processingLocation, promptVersion, fallbackUsed --
// sourced from "02.7 Normalize invoice (concept)"'s aiMeta, which is
// identical regardless of which provider lane ran. No secret or internal
// URL is ever included here.
const ctx = $input.first().json;
const org001 = ctx.org001;
const aiMeta = ctx.aiMeta || {};

let status, routing;
if (org001.outcome === "not_reliable") {
  status = "nicht_pruefbar";
  routing = "prioritized_review";
} else if (org001.outcome === "failed") {
  status = "klaerung_erforderlich";
  routing = "prioritized_review";
} else {
  status = "unauffaellig";
  routing = "standard_review";
}

return [{
  json: {
    correlationId: ctx.correlationId,
    status,
    routing,
    failedStep: null,
    errorCode: null,
    explanation: null,
    invoice: ctx.invoice,
    controls: [org001],
    organizationId: ctx.organizationId,
    processingPath: ctx.processingPath,
    aiExecutionProfile: ctx.aiExecutionProfile,
    aiProvider: aiMeta.aiProvider || null,
    modelId: aiMeta.modelId || null,
    modelVersion: aiMeta.modelVersion || null,
    processingLocation: aiMeta.processingLocation || null,
    promptVersion: aiMeta.promptVersion || null,
    fallbackUsed: aiMeta.fallbackUsed || false,
  },
}];

// Single convergence point for every success and failure branch. Renders
// self-contained HTML -- the demo audience must never need to inspect raw
// n8n execution JSON. A prominent notice states this is a temporary,
// n8n-side-only implementation (see the workflow-level and README notes).
const r = $input.first().json;

function esc(s) {
  if (s === null || s === undefined) return "";
  return String(s).replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
}

const statusColors = { unauffaellig: "#1b7a3d", klaerung_erforderlich: "#a15c00", nicht_pruefbar: "#a11616" };
const statusColor = statusColors[r.status] || "#444";

const aiSummary = r.aiExecutionProfile
  ? `<p><b>AI execution:</b> ${esc(r.aiExecutionProfile)} via ${esc(r.aiProvider) || "(none)"} ${esc(r.modelId) || ""} -- processed ${esc(r.processingLocation) || "(unknown)"}, prompt ${esc(r.promptVersion) || "(unknown)"}, fallback used: ${r.fallbackUsed ? "yes" : "no"}</p>`
  : "";

let body;
if (r.controls) {
  const inv = r.invoice;
  const rows = r.controls.map((c) => `
    <tr>
      <td>${esc(c.controlId)}</td>
      <td>${esc(c.title)}</td>
      <td>${esc(c.outcome)}</td>
      <td>${esc(c.severity)}</td>
      <td>${esc((c.reasonCodes || []).join(", "))}</td>
      <td>${esc(c.message)}</td>
      <td><pre>${esc(c.details ? JSON.stringify(c.details, null, 2) : "")}</pre></td>
    </tr>`).join("");

  body = `
    <h2>Invoice ${esc(inv.invoiceNumber || "(missing)")} dated ${esc(inv.issueDate || "(missing)")}</h2>
    <p><b>Supplier (as read by OCR/LLM, not verified):</b> ${esc(inv.supplier.name)}</p>
    <p><b>Buyer (as read by OCR/LLM):</b> ${esc(inv.buyer.name)}, ${esc(inv.buyer.address.street)}, ${esc(inv.buyer.address.postalCode)} ${esc(inv.buyer.address.city)}, ${esc(inv.buyer.address.countryCode)}</p>
    <p><b>Organization profile:</b> ${esc(r.organizationId)}</p>
    ${aiSummary}
    <h3>Controls</h3>
    <table border="1" cellpadding="6" cellspacing="0">
      <tr><th>Control</th><th>Title</th><th>Outcome</th><th>Severity</th><th>Reason codes</th><th>Message</th><th>Details</th></tr>
      ${rows}
    </table>`;
} else {
  body = `
    <h2>Technical result -- no control was evaluated</h2>
    <p><b>Failed step:</b> ${esc(r.failedStep)}</p>
    <p><b>Error code:</b> ${esc(r.errorCode)}</p>
    <p><b>Explanation:</b> ${esc(r.explanation)}</p>
    ${aiSummary}`;
}

const html = `<!doctype html>
<html><head><meta charset="utf-8"><title>DigiTax Flow 1b result</title>
<style>
  body { font-family: sans-serif; margin: 2rem; color: #1a1a1a; }
  .banner { padding: 1rem; border-radius: 6px; color: white; background: ${statusColor}; margin-bottom: 1rem; }
  .temp-notice { padding: 1rem; background: #fff3cd; border: 1px solid #d6b656; border-radius: 6px; margin-bottom: 1.5rem; }
  table { border-collapse: collapse; width: 100%; }
  th { background: #eee; text-align: left; }
  pre { white-space: pre-wrap; margin: 0; font-size: 0.85em; }
  .boundary { margin-top: 2rem; padding: 1rem; background: #f5f5f5; border-left: 4px solid #888; }
</style>
</head>
<body>
  <div class="temp-notice">
    <b>Flow 1b is a temporary n8n-side implementation.</b> OCR/LLM extraction
    (local or cloud, per the selected AI execution profile) is real; the
    ORG-001 evaluation below is computed in n8n, not by the Phase 1 API --
    POST /v1/invoices/process cannot yet consume OCR-extracted fields (its
    PDF adapter is a mock with no injection seam). This result is not yet
    interchangeable with a real API-issued control report. See
    examples/n8n/README.md for the missing adapter/API contract.
  </div>
  <div class="banner">
    <b>STATUS: ${esc(r.status)}</b> (routing: ${esc(r.routing)})<br>
    Correlation ID: ${esc(r.correlationId)}
  </div>
  ${body}
  <div class="boundary">
    This is a Flow 1b finding for human review only -- it is not an
    approval, rejection, booking, payment, or supplier communication.
  </div>
</body></html>`;

return [{ json: { ...r, html } }];
